<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Upload,Refresh,Download} from '@element-plus/icons-vue'
import ChartPanel from '../components/ChartPanel.vue'
import CompareImages from '../components/CompareImages.vue'
import {get,post,api,useTask,percent,number,scenes,methodLabel} from '../api/client'
const benchmarks=ref<any[]>([]),benchmarkId=ref('cbsr-nir')
const benchmark=computed(()=>benchmarks.value.find(b=>b.dataset===benchmarkId.value)||benchmarks.value[0])
const benchmarkRows=computed(()=>Object.entries(benchmark.value?.summary||{}).map(([method,value])=>({method,...(value as any).overall,delta:(value as any).delta_vs_original})))
const researchChart=computed(()=>({tooltip:{trigger:'axis' as const},legend:{bottom:0,data:['实测身份确认率','实测未知误接受率']},grid:{left:50,right:20,bottom:65,top:20},xAxis:{type:'category' as const,data:benchmarkRows.value.map(r=>methodLabel(r.method))},yAxis:{type:'value' as const,min:0,max:1,axisLabel:{formatter:(v:number)=>Math.round(v*100)+'%'}},series:[{name:'实测身份确认率',type:'bar' as const,data:benchmarkRows.value.map(r=>r.confirmation_rate),itemStyle:{color:'#2b8a72'}},{name:'实测未知误接受率',type:'bar' as const,data:benchmarkRows.value.map(r=>r.unknown_far),itemStyle:{color:'#d7aa6c'}}]}))
function interval(value:number[]|null|undefined){return value?.length===2?`${percent(value[0])} – ${percent(value[1])}`:'未评估'}
const datasets=ref<any[]>([]),experiments=ref<any[]>([]),calibrations=ref<any[]>([]),selected=ref<any>(null),results=ref<any[]>([])
const datasetId=ref<number>(),calibrationId=ref<number>(),threshold=ref(.45),targetFar=ref(.01),methods=ref(['original','gamma','clahe','retinex','adaptive'])
const zipInput=ref<HTMLInputElement>(),preview=ref<any>(null),datasetInfo=ref<any>(null),tab=ref('overview'),page=ref(1),selectedMethod=ref('adaptive')
const {busy,run}=useTask()
let timer:ReturnType<typeof setInterval>|undefined
let polling=false
const statusLabels:Record<string,string>={queued:'排队中',running:'运行中',completed:'已完成',failed:'失败'}
async function load(){[datasets.value,experiments.value,calibrations.value,benchmarks.value]=await Promise.all([get('/dataset'),get('/experiment'),get('/calibration'),get('/research/benchmarks')])}
async function choose(record:any){selected.value=await get('/experiment/'+record.id);page.value=1;await loadResults()}
async function loadResults(){if(selected.value)results.value=await get(`/experiment/${selected.value.id}/results?offset=${(page.value-1)*50}&limit=50`)}
onMounted(()=>{run(load);timer=setInterval(async()=>{if(polling||busy.value||!experiments.value.some(x=>['running','queued'].includes(x.status)))return;polling=true;try{await load();if(selected.value&&['running','queued'].includes(selected.value.status)){selected.value=await get('/experiment/'+selected.value.id);if(selected.value.status==='completed')await loadResults()}}catch{/* API interceptor handles failure */}finally{polling=false}},2500)})
onBeforeUnmount(()=>clearInterval(timer))
function importZip(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;run(async()=>{const form=new FormData();form.append('file',file);const result=await post('/dataset/import',form);datasetId.value=result.id;await load();ElMessage.success('数据集校验并导入完成')});(event.target as HTMLInputElement).value=''}
function start(){run(async()=>{const record=await post('/experiment/run',{dataset_id:datasetId.value,threshold:threshold.value,methods:methods.value,calibration_id:calibrationId.value||null});await load();await choose(record)})}
async function removeDataset(row:any){try{await ElMessageBox.confirm('删除此数据集及其全部图像？','删除数据集');await run(async()=>{await api.delete('/dataset/'+row.id);await load()})}catch{}}
async function removeExperiment(row:any){try{await ElMessageBox.confirm('删除此实验及逐样本结果？','删除实验');await run(async()=>{await api.delete('/experiment/'+row.id);if(selected.value?.id===row.id)selected.value=null;await load()})}catch{}}
function downloadTemplate(){const example={name:'请填写真实数据集名称',split:'test',source:'填写来源、采集设备及会话信息',license:'填写合法授权或受试者同意信息',real_capture:true,items:[{file:'images/example.png',scene:'normal',capture_id:'test-session-01',faces:[{bbox:[10,10,110,130],person_id:1,subject:'subject-001'}]}]};const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(example,null,2)],{type:'application/json'}));link.download='manifest.json';link.click();URL.revokeObjectURL(link.href)}
const summaryRows=computed(()=>Object.entries(selected.value?.summary || {}).map(([method,value])=>({method,...(value as any).overall,delta:(value as any).overall.confirmation_rate == null || selected.value?.summary?.original?.overall.confirmation_rate == null ? null : (value as any).overall.confirmation_rate-selected.value.summary.original.overall.confirmation_rate})))
const sceneRows=computed(()=>Object.entries(selected.value?.summary?.[selectedMethod.value]?.scenes || {}).map(([scene,value])=>({scene,...value as any})))
const chart=computed(()=>({tooltip:{trigger:'axis' as const},legend:{bottom:0,data:['身份确认率','检测召回率','未知误接受率']},grid:{left:50,right:20,bottom:65,top:20},xAxis:{type:'category' as const,data:summaryRows.value.map(r=>methodLabel(r.method))},yAxis:{type:'value' as const,min:0,max:1,axisLabel:{formatter:(v:number)=>Math.round(v*100)+'%'},splitLine:{lineStyle:{color:'#edf1ee'}}},series:[{name:'身份确认率',type:'bar' as const,data:summaryRows.value.map(r=>r.confirmation_rate),itemStyle:{color:'#2b8a72',borderRadius:[4,4,0,0]}},{name:'检测召回率',type:'bar' as const,data:summaryRows.value.map(r=>r.recall),itemStyle:{color:'#94b9c8',borderRadius:[4,4,0,0]}},{name:'未知误接受率',type:'bar' as const,data:summaryRows.value.map(r=>r.unknown_far),itemStyle:{color:'#d7aa6c',borderRadius:[4,4,0,0]}}]}))
</script>
<template><section class="card research-card"><div class="section-heading"><div><h2>真实公开数据评估</h2><el-button text :loading="busy" @click="run(load)">刷新评估结果</el-button><p class="muted">读取本机已完成的真实模型预测；场景证据与考核目标分别核对。</p></div><el-select v-if="benchmarks.length" v-model="benchmarkId" style="width:230px"><el-option v-for="b in benchmarks" :key="b.dataset" :value="b.dataset" :label="b.title"/></el-select></div><template v-if="benchmark"><el-alert :closable="false" type="info" :title="benchmark.dataset==='cbsr-nir'?'真实主动近红外数据，夜间环境和跨会话信息未提供；结果验证 NIR → NIR 协议，尚不能代替夜间补光验收。':'真实受控光照、紧裁剪输入；不同照明图像来自同次短时采集，不能代替独立实景逆光或夜间验收。'"/><div class="result-facts"><span>图库 <b>{{benchmark.gallery_subjects}} 人 / {{benchmark.gallery_accepted_images}} 张参考</b></span><span>校准 <b>{{benchmark.calibration_images}} 张</b></span><span>测试 <b>{{benchmark.test_images}} 张</b></span><span>模态 <b>{{benchmark.dataset==='cbsr-nir'?'NIR → NIR':'可见光受控光照'}}</b></span></div><ChartPanel :option="researchChart"/><p class="muted">各方法阈值在校准集分别冻结；差异包含增强与阈值的共同影响。相同固定阈值的补充对照见研究报告。</p><el-table :data="benchmarkRows"><el-table-column label="方法" min-width="120"><template #default="{row}">{{methodLabel(row.method)}}</template></el-table-column><el-table-column label="冻结阈值" min-width="100"><template #default="{row}">{{number(benchmark.thresholds[row.method],4)}}</template></el-table-column><el-table-column label="已知正确 / 总数" min-width="120"><template #default="{row}">{{row.correct}} / {{row.known}}</template></el-table-column><el-table-column label="身份确认率" min-width="105"><template #default="{row}">{{percent(row.confirmation_rate)}}</template></el-table-column><el-table-column label="Wilson 95% 区间" min-width="165"><template #default="{row}">{{interval(row.confirmation_ci95)}}</template></el-table-column><el-table-column label="按人员重采样区间" min-width="165"><template #default="{row}">{{interval(row.confirmation_subject_bootstrap_ci95)}}</template></el-table-column><el-table-column label="未知误接受" min-width="105"><template #default="{row}">{{row.false_accept}} / {{row.unknown}} · {{percent(row.unknown_far)}}<small style="display:block">95% 区间 {{interval(row.unknown_far_ci95)}}</small></template></el-table-column><el-table-column label="较原始变化" min-width="115"><template #default="{row}">{{row.delta==null?'—':(row.delta>=0?'+':'')+(row.delta*100).toFixed(1)+' 个百分点'}}</template></el-table-column></el-table><div class="target-grid"><div v-for="(value,key) in benchmark.summary.adaptive.targets" :key="key" class="note"><strong>{{String(key)==='overall'?'综合':scenes[String(key)]}} · 目标 {{percent((value as any).target)}}</strong><p>{{(value as any).status}}</p><small v-for="reason in (value as any).reasons" :key="reason" style="display:block">{{reason}}</small></div></div><el-collapse class="quality-card"><el-collapse-item title="评估范围、固定划分与场景证据"><p v-for="limit in benchmark.protocol.limitations" :key="limit" class="muted">{{limit}}</p><p class="muted">定位协议：{{benchmark.protocol.localization_protocol}}。仅眼点或单人脸存在性验证时，不将其当作 IoU 检测准确率。</p><pre class="json-panel">{{JSON.stringify(benchmark.protocol,null,2)}}</pre></el-collapse-item></el-collapse><div class="toolbar-actions quality-card"><a :href="`/api/research/benchmarks/${benchmark.dataset}/csv`" download><el-button :icon="Download">下载真实逐样本结果</el-button></a><el-button @click="run(async()=>{datasetInfo=await get(`/research/benchmarks/${benchmark.dataset}/protocol`)})">查看运行前冻结协议</el-button></div></template><el-empty v-else description="真实评估尚未完成；完成后点击刷新查看" :image-size="55"/></section><div class="experiment-top"><section class="card"><div class="section-heading"><h2>数据集管理</h2><div><input ref="zipInput" type="file" accept=".zip" class="sr-only" aria-label="导入数据集 ZIP" @change="importZip"><el-button :icon="Upload" :loading="busy" @click="zipInput?.click()">导入 ZIP</el-button></div></div><p class="muted">根目录包含 manifest.json 和标注图片，压缩包 ≤100 MB，最多 500 张图片。</p><el-table :data="datasets" max-height="280" empty-text="尚未导入真实标注数据"><el-table-column prop="name" label="数据集" min-width="130"/><el-table-column label="划分" width="100"><template #default="{row}"><el-tag size="small" :type="row.split==='test'?'success':'warning'">{{row.split==='test'?'测试':'校准'}}</el-tag></template></el-table-column><el-table-column prop="count" label="图像" width="65"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button link @click="run(async()=>{datasetInfo=await get('/dataset/'+row.id)})">详情</el-button><el-button link type="danger" @click="removeDataset(row)">删除</el-button></template></el-table-column></el-table><div class="note">标注需含场景、采集会话、人脸框与身份编号；未知身份设 person_id: null。红外场景必须来自真实红外采集。</div><el-button text @click="downloadTemplate">下载标注清单模板 ↓</el-button></section><section class="card"><div class="section-heading"><h2>创建消融实验</h2><span class="pill">固定模型与身份库</span></div><el-form label-position="top"><el-form-item label="数据集"><el-select v-model="datasetId" placeholder="选择数据集"><el-option v-for="d in datasets" :key="d.id" :label="d.name+' · '+d.split" :value="d.id"/></el-select></el-form-item><el-form-item label="实验组"><el-checkbox-group v-model="methods"><el-checkbox v-for="m in ['original','gamma','clahe','retinex','adaptive']" :key="m" :value="m">{{methodLabel(m)}}</el-checkbox></el-checkbox-group></el-form-item><div class="form-row"><el-form-item label="冻结阈值来源"><el-select v-model="calibrationId" clearable placeholder="手动阈值（探索性）"><el-option v-for="c in calibrations" :key="c.id" :value="c.id" :label="'校准 #'+c.id+' / 实验 #'+c.experiment_id"/></el-select></el-form-item><el-form-item v-if="!calibrationId" label="手动阈值"><el-input-number v-model="threshold" :min="-1" :max="1" :step=".01"/></el-form-item></div></el-form><el-button type="primary" :disabled="!datasetId||!methods.length" :loading="busy" @click="start">开始批量评估</el-button></section></div>
<section class="card quality-card"><div class="section-heading"><h2>实验任务</h2><el-button :icon="Refresh" text @click="run(load)">刷新</el-button></div><el-table :data="experiments" empty-text="尚无实验，所有场景均未评估"><el-table-column prop="id" label="编号" width="75"/><el-table-column label="数据集"><template #default="{row}">{{row.config.dataset.name}}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="row.status==='failed'?'danger':row.status==='completed'?'success':'info'">{{statusLabels[row.status]}}</el-tag></template></el-table-column><el-table-column label="进度" min-width="160"><template #default="{row}"><el-progress :percentage="row.total?Math.round(row.progress/row.total*100):0" :status="row.status==='failed'?'exception':undefined"/></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="run(()=>choose(row))">查看结果</el-button><el-button link type="danger" :disabled="['queued','running'].includes(row.status)" @click="removeExperiment(row)">删除</el-button></template></el-table-column></el-table></section>
<section v-if="selected" class="card quality-card"><div class="section-heading"><div><h2>实验 #{{selected.id}} <el-tag size="small">{{statusLabels[selected.status]}}</el-tag></h2><p class="muted">{{selected.config.calibration_note}}</p></div><a :href="'/api/experiment/'+selected.id+'/csv'" download><el-button :icon="Download">导出逐样本 CSV</el-button></a></div><el-alert v-if="selected.error" :title="selected.error" type="error" :closable="false"/><el-alert v-if="!selected.config.dataset.real_capture" title="此数据集标记为合成/派生数据，仅用于流程验证，不用于声明真实场景指标达标。" type="warning" :closable="false"/><el-alert v-if="selected.config.localization_protocol&&selected.config.localization_protocol!=='iou'" :closable="false" type="info" :title="'定位协议为 '+selected.config.localization_protocol+'，下方检测列仅适用于此协议，不代表 IoU 定位精度。'"/><el-tabs v-model="tab"><el-tab-pane label="算法对比" name="overview"><ChartPanel :option="chart"/><el-table :data="summaryRows"><el-table-column label="增强方法" min-width="130"><template #default="{row}">{{methodLabel(row.method)}}</template></el-table-column><el-table-column prop="images" label="图像数"/><el-table-column label="检测精确率"><template #default="{row}">{{percent(row.precision)}}</template></el-table-column><el-table-column label="检测召回率"><template #default="{row}">{{percent(row.recall)}}</template></el-table-column><el-table-column label="身份确认率"><template #default="{row}">{{percent(row.confirmation_rate)}}</template></el-table-column><el-table-column label="较原始变化"><template #default="{row}">{{row.delta==null?'—':(row.delta>=0?'+':'')+(row.delta*100).toFixed(1)+' 个百分点'}}</template></el-table-column><el-table-column label="未知误接受率"><template #default="{row}">{{percent(row.unknown_far)}}</template></el-table-column><el-table-column label="平均耗时"><template #default="{row}">{{number(row.mean_ms)}} ms</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="分场景统计" name="scenes"><el-select v-model="selectedMethod" style="width:220px"><el-option v-for="m in selected.config.methods" :key="m" :value="m" :label="methodLabel(m)"/></el-select><el-table :data="sceneRows"><el-table-column label="场景"><template #default="{row}">{{scenes[row.scene]}}</template></el-table-column><el-table-column prop="images" label="图像数"/><el-table-column prop="known" label="已知人脸数"/><el-table-column prop="unknown" label="未知人脸数"/><el-table-column label="身份确认率"><template #default="{row}">{{percent(row.confirmation_rate)}}</template></el-table-column><el-table-column label="误接受率"><template #default="{row}">{{percent(row.unknown_far)}}</template></el-table-column></el-table><div class="target-grid"><div v-for="(value,key) in selected.summary?.[selectedMethod]?.targets" :key="key" class="note"><strong>{{String(key)==='overall'?'综合':scenes[String(key)]}} · 目标 {{percent((value as any).target)}}</strong><p>{{(value as any).status}}</p><small v-for="reason in (value as any).reasons" :key="reason" style="display:block">{{reason}}</small></div></div></el-tab-pane><el-tab-pane label="逐样本结果" name="samples"><el-table :data="results"><el-table-column prop="item_index" label="样本索引"/><el-table-column label="方法"><template #default="{row}">{{methodLabel(row.method)}}</template></el-table-column><el-table-column label="场景"><template #default="{row}">{{scenes[row.scene]}}</template></el-table-column><el-table-column prop="tp" label="TP"/><el-table-column prop="fp" label="FP"/><el-table-column prop="fn" label="FN"/><el-table-column prop="correct" label="确认正确"/><el-table-column label="图像"><template #default="{row}"><el-button link type="primary" @click="run(async()=>{preview=await get(`/experiment/${selected.id}/preview/${row.id}`)})">查看对比</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="selected.progress" :page-size="50" layout="prev,pager,next,total" @current-change="run(loadResults)"/></el-tab-pane><el-tab-pane label="复现配置" name="config"><pre class="json-panel">{{JSON.stringify(selected.config,null,2)}}</pre></el-tab-pane></el-tabs><div v-if="selected.status==='completed'&&selected.config.split==='calibration'" class="calibration-bar"><span>从此校准实验选择阈值 · 目标 FAR</span><el-input-number v-model="targetFar" :min="0" :max=".2" :step=".01"/><el-button :loading="busy" @click="run(async()=>{await post('/calibration',{experiment_id:selected.id,target_far:targetFar});await load();ElMessage.success('校准阈值已保存，测试时可选择')})">计算并冻结阈值</el-button></div></section><div v-else class="note quality-card">缺少真实测试数据的场景一律显示“未评估”。综合身份确认率按样本总数汇总，不对场景百分比取平均。</div>
<el-dialog :model-value="!!preview" title="实验图像对比" width="900px" @close="preview=null"><CompareImages :original="preview?.original" :enhanced="preview?.enhanced"/></el-dialog><el-dialog :model-value="!!datasetInfo" title="数据集元信息与标注" width="760px" @close="datasetInfo=null"><pre class="json-panel">{{JSON.stringify(datasetInfo,null,2)}}</pre></el-dialog></template>
